import java.util.Arrays;import java.util.Scanner;
public class ReverseArray { public static void main(String[]args){Scanner sc=new Scanner(System.in);System.out.print("Enter array size: ");int n=sc.nextInt();if(n<0){System.out.println("Invalid size.");sc.close();return;}int[]arr=new int[n];System.out.println("Enter elements:");for(int i=0;i<n;i++)arr[i]=sc.nextInt();int l=0,r=n-1;while(l<r){int t=arr[l];arr[l]=arr[r];arr[r]=t;l++;r--;}System.out.println(Arrays.toString(arr));sc.close();} }